import sys

def solve():
    s = sys.stdin.read().strip()
    n = len(s)
    if n == 0:
        return

    res = [''] * n
    dp = [None] * (n + 1)
    dp[n] = ''

    for i in range(n - 1, -1, -1):
        best = dp[i + 1]
        if i + 1 < n and s[i] == s[i + 1]:
            cand = dp[i + 2]
            if len(cand) < len(best) or (len(cand) == len(best) and cand < best):
                best = cand
            elif len(cand) == len(best) and cand == best:
                pass
        res[i] = best

    out_lines = []
    for i in range(n):
        ans = res[i]
        length = len(ans)
        if length == 0:
            out_lines.append(f"{length} ")
        elif length <= 10:
            out_lines.append(f"{length} {ans}")
        else:
            out_lines.append(f"{length} {ans[:5]}...{ans[-2:]}")

    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == "__main__":
    solve()
